from collections import deque

MAX_RECEIVE = 3
queue = deque([("m1", "ok"), ("m2", "poison"), ("m3", "ok")])
receive_count = {}
dlq = []

def process(body):
    if body == "poison":
        raise ValueError("cannot parse")      # a bug that retrying never fixes
    return "done"

while queue:
    mid, body = queue.popleft()
    receive_count[mid] = receive_count.get(mid, 0) + 1
    try:
        print(mid, "attempt", receive_count[mid], process(body))
    except ValueError:
        if receive_count[mid] >= MAX_RECEIVE:   # moved to the DLQ, loop ends
            dlq.append(mid)
            print(mid, "moved to DLQ after", receive_count[mid], "receives")
        else:
            queue.append((mid, body))           # visibility timeout expires, it returns
            print(mid, "failed, will reappear")
print("DLQ contents:", dlq)
